const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
if (data.length === 0) process.exit(0);

const n = Number(data[0]);
const adj = Array.from({ length: n + 1 }, () => []);

let idx = 1;
for (let i = 0; i < n - 1; i++) {
  const a = Number(data[idx++]);
  const b = Number(data[idx++]);
  adj[a].push(b);
  adj[b].push(a);
}

const parent = new Int32Array(n + 1);
const order = new Int32Array(n);
let orderLen = 0;

const stack = [1];
parent[1] = 0;

while (stack.length > 0) {
  const v = stack.pop();
  order[orderLen++] = v;

  const neighbors = adj[v];
  for (let i = 0; i < neighbors.length; i++) {
    const u = neighbors[i];
    if (u !== parent[v]) {
      parent[u] = v;
      stack.push(u);
    }
  }
}

const size = new Int32Array(n + 1);
for (let i = 1; i <= n; i++) size[i] = 1;

let answer = n;

for (let i = orderLen - 1; i >= 0; i--) {
  const v = order[i];
  const p = parent[v];

  if (p !== 0) {
    const s = size[v];
    const diff = n - 2 * s;
    const absDiff = diff < 0 ? -diff : diff;
    if (absDiff < answer) answer = absDiff;
    size[p] += s;
  }
}

console.log(answer);
